using System.Data;
using Cosmos.Application.Abstractions.Persistence;
using Cosmos.Application.PurchaseExpense;
using Cosmos.Contracts.Common;
using Cosmos.Contracts.PurchaseExpense;
using Cosmos.Persistence.Connection;
using Cosmos.Persistence.Dapper;
using Cosmos.Shared.Exceptions;
using Dapper;

namespace Cosmos.Persistence.Repositories;

public sealed class PurchaseExpenseRepository(ISqlConnectionFactory factory) : IPurchaseExpenseRepository
{
    public Task<bool> SupplierExistsAsync(Guid id,CancellationToken ct)=>Scalar<bool>("sp_PurchaseExpense_SupplierExists",new{Id=id},ct); public Task<bool> ItemExistsAsync(long id,CancellationToken ct)=>Scalar<bool>("sp_PurchaseExpense_ItemExists",new{Id=id},ct); public Task<bool> ExpenseCategoryExistsAsync(long id,CancellationToken ct)=>Scalar<bool>("sp_ExpenseCategory_Exists",new{Id=id},ct);
    public Task<PagedResult<PurchaseBillDto>> GetPurchaseBillsAsync(PurchaseBillListQuery q,CancellationToken ct)=>PagedWithSummary<PurchaseBillDto,PurchaseBillListSummaryDto>("sp_PurchaseBill_GetList","sp_PurchaseBill_GetListSummary",q,q.PageNumber,q.PageSize,ct); public Task<PurchaseBillDetailDto?> GetPurchaseBillAsync(long id,CancellationToken ct)=>Bill(id,ct);
    public async Task<PurchaseBillDetailDto> CreatePurchaseBillAsync(CreatePurchaseBillRequest r,long? u,CancellationToken ct){var id=await SaveId("sp_PurchaseBill_Save",BillParams(null,r,u),ct);return (await Bill(id,ct))!;} public async Task<PurchaseBillDetailDto> UpdatePurchaseBillAsync(long id,UpdatePurchaseBillRequest r,long? u,CancellationToken ct){var x=new CreatePurchaseBillRequest(r.SupplierId,r.SupplierInvoiceNo,r.BillDate,r.DueDate,r.PaymentType,r.Items,r.DiscountAmount,r.RoundOff,r.PaidAmount,r.Notes);await SaveId("sp_PurchaseBill_Save",BillParams(id,x,u),ct);return (await Bill(id,ct))!;}
    public async Task<PurchaseBillDetailDto> ChangePurchaseBillStatusAsync(long id,bool confirm,long? u,CancellationToken ct){await Status(confirm?"sp_PurchaseBill_Confirm":"sp_PurchaseBill_Cancel",new{Id=id,UserId=u},ct);return (await Bill(id,ct))!;} public Task DeletePurchaseBillAsync(long id,long? u,CancellationToken ct)=>Status("sp_PurchaseBill_Delete",new{Id=id,UserId=u},ct);
    public Task<PagedResult<SupplierPaymentDto>> GetSupplierPaymentsAsync(SupplierPaymentListQuery q,CancellationToken ct)=>PagedWithSummary<SupplierPaymentDto,SupplierPaymentListSummaryDto>("sp_SupplierPayment_GetList","sp_SupplierPayment_GetListSummary",q,q.PageNumber,q.PageSize,ct); public async Task<SupplierPaymentDto?> GetSupplierPaymentAsync(long id,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);var cmd=new CommandDefinition("sp_SupplierPayment_GetById",new{Id=id},commandType:CommandType.StoredProcedure,cancellationToken:ct);using var m=await c.QueryMultipleAsync(cmd);var x=await m.ReadSingleOrDefaultAsync<SupplierPaymentDto>();if(x is not null)x.Allocations=(await m.ReadAsync<SupplierPaymentAllocationDto>()).AsList();return x;}
    public async Task<SupplierPaymentDto> SaveSupplierPaymentAsync(long? id,CreateSupplierPaymentRequest r,long? u,CancellationToken ct){var p=new{Id=id,r.SupplierId,r.PaymentDate,r.Amount,r.PaymentMode,r.ReferenceNo,r.Notes,Allocations=Allocations(r.Allocations).AsTableValuedParameter("dbo.SupplierPaymentAllocationInput"),UserId=u};var saved=await SaveId("sp_SupplierPayment_Save",p,ct);return (await GetSupplierPaymentAsync(saved,ct))!;} public Task DeleteSupplierPaymentAsync(long id,long? u,CancellationToken ct)=>Status("sp_SupplierPayment_Delete",new{Id=id,UserId=u},ct);
    public Task<PagedResult<ExpenseCategoryDto>> GetExpenseCategoriesAsync(ExpenseCategoryListQuery q,CancellationToken ct)=>PagedWithSummary<ExpenseCategoryDto,Cosmos.Contracts.Items.MasterListSummaryDto>("sp_ExpenseCategory_GetList","sp_ExpenseCategory_GetListSummary",q,q.PageNumber,q.PageSize,ct); public Task<ExpenseCategoryDto?> GetExpenseCategoryAsync(long id,CancellationToken ct)=>Single<ExpenseCategoryDto>("sp_ExpenseCategory_GetById",new{Id=id},ct); public async Task<ExpenseCategoryDto> SaveExpenseCategoryAsync(long? id,CreateExpenseCategoryRequest r,long? u,CancellationToken ct){var saved=await SaveId("sp_ExpenseCategory_Save",new{Id=id,r.Name,r.Description,r.IsActive,UserId=u},ct);return (await GetExpenseCategoryAsync(saved,ct))!;} public Task DeleteExpenseCategoryAsync(long id,long? u,CancellationToken ct)=>Status("sp_ExpenseCategory_Delete",new{Id=id,UserId=u},ct);
    public Task<PagedResult<ExpenseDto>> GetExpensesAsync(ExpenseListQuery q,CancellationToken ct)=>PagedWithSummary<ExpenseDto,ExpenseListSummaryDto>("sp_Expense_GetList","sp_Expense_GetListSummary",q,q.PageNumber,q.PageSize,ct); public Task<ExpenseDto?> GetExpenseAsync(long id,CancellationToken ct)=>Single<ExpenseDto>("sp_Expense_GetById",new{Id=id},ct); public async Task<ExpenseDto> SaveExpenseAsync(long? id,CreateExpenseRequest r,long? u,CancellationToken ct){var saved=await SaveId("sp_Expense_Save",new{Id=id,r.ExpenseDate,r.CategoryId,r.PaidToPartyId,r.Amount,r.TaxAmount,r.PaymentMode,r.ReferenceNo,r.Notes,r.AttachmentPath,UserId=u},ct);return (await GetExpenseAsync(saved,ct))!;} public Task DeleteExpenseAsync(long id,long? u,CancellationToken ct)=>Status("sp_Expense_Delete",new{Id=id,UserId=u},ct);
    public Task<PagedResult<PurchaseOrderDto>> GetPurchaseOrdersAsync(PurchaseOrderListQuery q,CancellationToken ct)=>PagedWithSummary<PurchaseOrderDto,PurchaseOrderListSummaryDto>("sp_PurchaseOrder_GetList","sp_PurchaseOrder_GetListSummary",q,q.PageNumber,q.PageSize,ct); public Task<PurchaseOrderDetailDto?> GetPurchaseOrderAsync(long id,CancellationToken ct)=>Order(id,ct); public async Task<PurchaseOrderDetailDto> SavePurchaseOrderAsync(long? id,CreatePurchaseOrderRequest r,long? u,CancellationToken ct){var p=new{Id=id,r.SupplierId,r.OrderDate,r.ExpectedDeliveryDate,r.DiscountAmount,r.TermsAndConditions,r.Notes,Items=Lines(r.Items).AsTableValuedParameter("dbo.PurchaseLineInput"),UserId=u};var saved=await SaveId("sp_PurchaseOrder_Save",p,ct);return (await Order(saved,ct))!;} public Task DeletePurchaseOrderAsync(long id,long? u,CancellationToken ct)=>Status("sp_PurchaseOrder_Delete",new{Id=id,UserId=u},ct); public async Task<PurchaseOrderDetailDto> CancelPurchaseOrderAsync(long id,long? u,CancellationToken ct){await Status("sp_PurchaseOrder_Cancel",new{Id=id,UserId=u},ct);return (await Order(id,ct))!;} public async Task<PurchaseBillDetailDto> ConvertPurchaseOrderAsync(long id,ConvertPurchaseOrderRequest r,long? u,CancellationToken ct){var saved=await SaveId("sp_PurchaseOrder_Convert",new{Id=id,r.BillDate,r.DueDate,r.PaymentType,r.PaidAmount,r.SupplierInvoiceNo,UserId=u},ct);return (await Bill(saved,ct))!;}
    public Task<PagedResult<PurchaseReturnDto>> GetPurchaseReturnsAsync(PurchaseReturnListQuery q,CancellationToken ct)=>PagedWithSummary<PurchaseReturnDto,PurchaseReturnListSummaryDto>("sp_PurchaseReturn_GetList","sp_PurchaseReturn_GetListSummary",q,q.PageNumber,q.PageSize,ct); public Task<PurchaseReturnDetailDto?> GetPurchaseReturnAsync(long id,CancellationToken ct)=>Return(id,ct); public async Task<PurchaseReturnDetailDto> SavePurchaseReturnAsync(long? id,CreatePurchaseReturnRequest r,long? u,CancellationToken ct){var p=new{Id=id,r.PurchaseBillId,r.SupplierId,r.ReturnDate,r.Reason,r.Notes,Items=Lines(r.Items).AsTableValuedParameter("dbo.PurchaseLineInput"),UserId=u};var saved=await SaveId("sp_PurchaseReturn_Save",p,ct);return (await Return(saved,ct))!;} public Task DeletePurchaseReturnAsync(long id,long? u,CancellationToken ct)=>Status("sp_PurchaseReturn_Delete",new{Id=id,UserId=u},ct);
    public Task<PurchaseSummaryDto> GetPurchaseSummaryAsync(DateRangeReportQuery q,CancellationToken ct)=>SingleRequired<PurchaseSummaryDto>("sp_PurchaseExpenseReport_PurchaseSummary",q,ct); public Task<IReadOnlyCollection<SupplierOutstandingDto>> GetSupplierOutstandingAsync(CancellationToken ct)=>Many<SupplierOutstandingDto>("sp_PurchaseExpenseReport_SupplierOutstanding",null,ct); public Task<ExpenseSummaryDto> GetExpenseSummaryAsync(DateRangeReportQuery q,CancellationToken ct)=>SingleRequired<ExpenseSummaryDto>("sp_PurchaseExpenseReport_ExpenseSummary",q,ct); public Task<IReadOnlyCollection<CategoryWiseExpenseDto>> GetCategoryWiseExpenseAsync(DateRangeReportQuery q,CancellationToken ct)=>Many<CategoryWiseExpenseDto>("sp_PurchaseExpenseReport_CategoryWiseExpense",q,ct); public Task<IReadOnlyCollection<ItemPurchaseHistoryDto>> GetItemPurchaseHistoryAsync(long itemId,CancellationToken ct)=>Many<ItemPurchaseHistoryDto>("sp_PurchaseExpenseReport_ItemPurchaseHistory",new{ItemId=itemId},ct);
    private object BillParams(long? id,CreatePurchaseBillRequest r,long? u)=>new{Id=id,r.SupplierId,r.SupplierInvoiceNo,r.BillDate,r.DueDate,r.PaymentType,r.DiscountAmount,r.RoundOff,r.PaidAmount,r.Notes,Items=Lines(r.Items).AsTableValuedParameter("dbo.PurchaseLineInput"),UserId=u};
    private async Task<PurchaseBillDetailDto?> Bill(long id,CancellationToken ct)=>await Detail<PurchaseBillDetailDto>("sp_PurchaseBill_GetById",id,ct); private async Task<PurchaseOrderDetailDto?> Order(long id,CancellationToken ct)=>await Detail<PurchaseOrderDetailDto>("sp_PurchaseOrder_GetById",id,ct); private async Task<PurchaseReturnDetailDto?> Return(long id,CancellationToken ct)=>await Detail<PurchaseReturnDetailDto>("sp_PurchaseReturn_GetById",id,ct);
    private async Task<T?> Detail<T>(string sp,long id,CancellationToken ct) where T:class {using var c=await factory.CreateOpenConnectionAsync(ct);using var m=await c.QueryMultipleAsync(new CommandDefinition(sp,new{Id=id},commandType:CommandType.StoredProcedure,cancellationToken:ct));var x=await m.ReadSingleOrDefaultAsync<T>();var lines=(await m.ReadAsync<PurchaseLineDto>()).AsList();if(x is PurchaseBillDetailDto b)b.Items=lines;else if(x is PurchaseOrderDetailDto o)o.Items=lines;else if(x is PurchaseReturnDetailDto r)r.Items=lines;return x;}
    private async Task<PagedResult<T>> Paged<T>(string sp,object p,int page,int size,CancellationToken ct){var rows=await Many<T>(sp,p,ct);var count=rows.FirstOrDefault() is null?0:(int)(typeof(T).GetProperty("TotalCount")?.GetValue(rows.First())??0);return new(rows,page,size,count);} private async Task<PagedResult<T>> PagedWithSummary<T,TSummary>(string sp,string summarySp,object p,int page,int size,CancellationToken ct) where TSummary:class {var rows=await Many<T>(sp,p,ct);var summary=await Single<TSummary>(summarySp,p,ct)??throw new InvalidOperationException($"{summarySp} returned no row.");var count=(int)(typeof(TSummary).GetProperty("TotalCount")?.GetValue(summary)??0);return new(rows,page,size,count,summary);} private async Task<IReadOnlyCollection<T>> Many<T>(string sp,object? p,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return await StoredProcedureExecutor.QueryAsync<T>(c,sp,p,ct);} private async Task<T?> Single<T>(string sp,object? p,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return await StoredProcedureExecutor.QuerySingleOrDefaultAsync<T>(c,sp,p,ct);} private async Task<T> SingleRequired<T>(string sp,object? p,CancellationToken ct)=>await Single<T>(sp,p,ct)??throw new InvalidOperationException($"{sp} returned no row."); private async Task<T> Scalar<T>(string sp,object p,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return (await c.ExecuteScalarAsync<T>(new CommandDefinition(sp,p,commandType:CommandType.StoredProcedure,cancellationToken:ct)))!;}
    private async Task<long> SaveId(string sp,object p,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);return await StoredProcedureExecutor.QueryWithStatusAsync<long>(c,sp,p,ct);} private async Task Status(string sp,object p,CancellationToken ct){using var c=await factory.CreateOpenConnectionAsync(ct);var x=await StoredProcedureExecutor.ExecuteStatusAsync(c,sp,p,ct);if(!x.Succeeded)throw new CosmosException(x.Message,x.StatusCode);}
    private static DataTable Lines(IEnumerable<PurchaseLineRequest> lines){var t=new DataTable();t.Columns.Add("ItemId",typeof(long));t.Columns.Add("Quantity",typeof(decimal));t.Columns.Add("PurchasePrice",typeof(decimal));t.Columns.Add("DiscountPercentage",typeof(decimal));t.Columns.Add("DiscountAmount",typeof(decimal));t.Columns.Add("TaxPercentage",typeof(decimal));t.Columns.Add("UnitId",typeof(long));t.Columns.Add("PurchaseBillItemId",typeof(long));foreach(var x in lines)t.Rows.Add(x.ItemId,x.Quantity,x.PurchasePrice,x.DiscountPercentage,x.DiscountAmount,x.TaxPercentage,x.UnitId??(object)DBNull.Value,x.PurchaseBillItemId??(object)DBNull.Value);return t;}
    private static DataTable Allocations(IEnumerable<SupplierPaymentAllocationRequest>? values){var t=new DataTable();t.Columns.Add("PurchaseBillId",typeof(long));t.Columns.Add("AllocatedAmount",typeof(decimal));foreach(var x in values??[])t.Rows.Add(x.PurchaseBillId,x.AllocatedAmount);return t;}
}
